import json
import os
from collections import defaultdict

class DualTimelineRAG:
    """
    Dual Timeline RAG handles:
    1. Route History (Causal Player Unlocks - DAG)
    2. Universal Lore (Chronological Story Universe)
    """
    def __init__(self, scenes_file, timeline_file=None):
        self.scenes_file = scenes_file
        self.scenes = []
        self.scene_lookup = {}
        self.dag_parents = defaultdict(list)
        
        # Simulated Universal Lore DB (Generated by SummarizerAgent in Phase 1)
        self.universal_lore = [
            {"phase": 1, "description": "Shion's past as an idol named Hikari."},
            {"phase": 2, "description": "Shion arrives at the island / vacation."},
            {"phase": 3, "description": "Shion works at the bakery and gets close to Masaru."},
            {"phase": 4, "description": "Late game events / endings."}
        ]
        
        self._load_data()

    def _load_data(self):
        print(f"Loading data from {self.scenes_file}...")
        with open(self.scenes_file, "r", encoding="utf-8") as f:
            self.scenes = json.load(f)
            
        # Reconstruct DAG backwards for Route History
        state_providers = defaultdict(list)
        scene_requirements = defaultdict(list)
        
        for scene in self.scenes:
            source = scene["source"]
            self.scene_lookup[source] = scene
            
            # Map requirements
            for cond in scene.get("conditions", []):
                import re
                match = re.search(r"Requires (.*?) (==|>=) (.*)", cond)
                if match:
                    scene_requirements[source].append(match.group(1).strip())
                    
            # Map providers
            for change in scene.get("state_changes", []):
                if change.startswith("Set "):
                    parts = change.split(" to ")
                    if len(parts) == 2:
                        state_providers[parts[0][4:].strip()].append(source)
                elif change.startswith("Mod "):
                    parts = change.split(" ")
                    if len(parts) >= 3:
                        state_providers[parts[1].strip()].append(source)
                        
        # Link parents
        for scene in self.scenes:
            source = scene["source"]
            for req in scene_requirements[source]:
                for provider in state_providers.get(req, []):
                    if provider != source:
                        self.dag_parents[source].append(provider)

    def get_universal_lore(self, target_phase):
        """
        Returns story lore strictly UP TO the target phase.
        Hides future spoilers.
        """
        valid_lore = [lore for lore in self.universal_lore if lore["phase"] <= target_phase]
        return valid_lore

    def get_route_history(self, target_scene_id, depth=5):
        """
        Walks backwards up the DAG to fetch the exact scenes the player experienced 
        before unlocking this scene.
        """
        history = []
        visited = set()
        
        def traverse(node, current_depth):
            if current_depth > depth or node in visited:
                return
            visited.add(node)
            parents = self.dag_parents.get(node, [])
            for p in parents:
                if p in self.scene_lookup:
                    history.append(self.scene_lookup[p])
                    traverse(p, current_depth + 1)
                    
        traverse(target_scene_id, 1)
        return history

